var inMemoryBills = [...INITIAL_MAINTENANCE_BILLS];
function getStoredBills() {
  if (typeof window !== "undefined") {
    try {
      const activeId = getActiveSocietyId();
      const storageKey = getSocietyStorageKey(STORAGE_KEY_BILLS, activeId);
      const stored = localStorage.getItem(storageKey);
      if (stored !== null) {
        return JSON.parse(stored);
      }
      if (isSocietyCleanData(activeId)) return [];
    } catch {
    }
  }
  return isSocietyCleanData(getActiveSocietyId()) ? [] : inMemoryBills;
}
function saveBills(bills) {
  inMemoryBills = bills;
  if (typeof window !== "undefined") {
    try {
      const activeId = getActiveSocietyId();
      const storageKey = getSocietyStorageKey(STORAGE_KEY_BILLS, activeId);
      localStorage.setItem(storageKey, JSON.stringify(bills));
    } catch {
    }
  }
}
function getMaintenanceBills(flatNumber) {
  const allBills = getStoredBills();
  if (!flatNumber) return allBills;
  const normalized = flatNumber.trim().toLowerCase();
  return allBills.filter(
    (b) => b.flatNumber.toLowerCase() === normalized || b.flatNumber.toLowerCase().includes(normalized)
  );
}
function getMaintenanceSummary() {
  const bills = getStoredBills();
  const currentMonthBills = bills.filter((b) => b.month === "September 2026");
  const totalFlats = 128;
  const targetBilled = totalFlats * 3850;
  let totalCollected = 0;
  let totalOutstanding = 0;
  let paidFlatsCount = 0;
  let pendingFlatsCount = 0;
  let overdueFlatsCount = 0;
  currentMonthBills.forEach((b) => {
    if (b.status === "paid") {
      totalCollected += b.totalAmount;
      paidFlatsCount++;
    } else if (b.status === "overdue") {
      totalOutstanding += b.totalAmount;
      overdueFlatsCount++;
    } else {
      totalOutstanding += b.totalAmount;
      pendingFlatsCount++;
    }
  });
  const estimatedCollected = 412e3 + paidFlatsCount * 3850;
  const estimatedOutstanding = targetBilled - estimatedCollected;
  const collectionRate = Math.min(100, Math.round(estimatedCollected / targetBilled * 100));
  return {
    totalBilled: targetBilled,
    totalCollected: estimatedCollected,
    totalOutstanding: Math.max(0, estimatedOutstanding),
    totalFlats,
    paidFlatsCount: 104 + paidFlatsCount,
    pendingFlatsCount: Math.max(0, 18 - paidFlatsCount),
    overdueFlatsCount: 6,
    collectionRate
  };
}
